from math import comb

def miss_probability(n, r, w):
    # By symmetry, fix the write set. The read misses it exactly when all r
    # replicas it asks come from the n - w replicas the write skipped.
    return comb(n - w, r) / comb(n, r)

def handle_request_vote(state, req):
    if req["term"] < state["term"]:
        return False
    if req["term"] > state["term"]:
        state["term"] = req["term"]
        state["voted_for"] = None
    up_to_date = (req["last_log_term"] > state["last_log_term"] or
                  (req["last_log_term"] == state["last_log_term"] and
                   req["last_log_index"] >= state["last_log_index"]))
    if state["voted_for"] in (None, req["candidate"]) and up_to_date:
        state["voted_for"] = req["candidate"]
        return True
    return False

